mapper.select:
SELECT CAST(c.id AS CHAR) AS id, c.user_id AS userId, u.nickname AS userNickname, c.title, c.message_count AS messageCount, c.last_message_at AS lastMessageAt, c.deleted, c.created_at AS createdAt FROM qa_conversations c LEFT JOIN users u ON c.user_id = u.id
AND c.deleted = 0
AND c.user_id = #{userId}
AND c.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY COALESCE(c.last_message_at, c.created_at) DESC, c.id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE qa_conversations
SET deleted = 1, updated_at = NOW()
WHERE id = #{id}

